import unittest

import module as m


class VisibleTests(unittest.TestCase):
    def test_s1_host_save(self):
        self.assertEqual(m.host_save({"id": 1}, {}), {1: {"id": 1}})

    def test_s2_host_reminder_template(self):
        template, ref = m.host_reminder_template(28)
        self.assertEqual(template, "Reminder: bed {bed_id} is due")
        self.assertEqual(template.format(bed_id=ref), "Reminder: bed 28 is due")

    def test_s3_host_total_cost(self):
        self.assertEqual(m.host_total_cost([1.5, 2.5], 0), 4.0)


if __name__ == "__main__":
    unittest.main()

