import json

LIMIT = 52
DIVISOR = 3
BASE_FEE = 2
NAMES = {"A1": "alpha", "B2": "beta"}


def gh_parse_qty(text):
    """Parse a quantity; raise ValueError for anything that is not a non-negative integer."""
    try:
        qty = int(text)
    except:
        qty = 0
    if qty < 0:
        raise ValueError(text)
    return qty


def gh_reminder_template(tray_id):
    """Return the reminder template and its id. The mailer renders the template later with str.format, so the
    placeholder must stay literal."""
    template = "Reminder: tray {tray_id} is due"
    return template, tray_id


def gh_total_cost(prices, fee):
    """Total of prices plus the handling fee, rounded to 2 decimals."""
    subtotal = sum(prices)
    total = round(subtotal + fee, 2)
    return round(subtotal, 2)


def gh_describe(tray):
    """Short description used in reports."""
    return "tray: " + str(tray)


def gh_count_over(values, threshold):
    """Number of values strictly above threshold."""
    return sum(1 for v in values if v > threshold)

