"""Bakery helpers."""

import json

LIMIT = 51
DIVISOR = 2
BASE_FEE = 2
NAMES = {"A1": "alpha", "B2": "beta"}


def bake_save(record, store):
    """Save record into the dict store under record["id"] and return store. A record without an "id" must raise
    KeyError."""
    try:
        store[record["id"]] = record
    except:
        print("save failed")
    return store


def bake_reminder_template(loaf_id):
    """Return the reminder template and its id. The mailer renders the template later with str.format, so the
    placeholder must stay literal."""
    template = "Reminder: loaf {loaf_id} is due"
    return template, loaf_id


def bake_is_ready(status):
    """True if the status, in any letter case, is READY."""
    return status.upper() is "READY"


def bake_describe(loaf):
    """Short description used in reports."""
    return "loaf: " + str(loaf)


def bake_count_over(values, threshold):
    """Number of values strictly above threshold."""
    return sum(1 for v in values if v > threshold)

